def diff_record(api, row, mapping):
    out = []
    for field, column in mapping.items():
        a, b = api.get(field), row.get(column)
        if field == 'email' and isinstance(a, str) and isinstance(b, str):
            a, b = a.strip().lower(), b.strip().lower()
        if a != b:
            out.append(field)
    return sorted(out)
